from pathlib import Path
import os, stat, hashlib, json
root = Path('/work')
for name in ('AGENTS.md','CLAUDE.md'):
    p = root / name
    try:
        st = os.lstat(p)
        info = {
            'path': str(p),
            'exists_lstat': True,
            'type': 'symlink' if stat.S_ISLNK(st.st_mode) else 'regular' if stat.S_ISREG(st.st_mode) else 'directory' if stat.S_ISDIR(st.st_mode) else 'other',
            'mode': oct(stat.S_IMODE(st.st_mode)),
            'uid': st.st_uid,
            'gid': st.st_gid,
            'size': st.st_size,
        }
        if stat.S_ISLNK(st.st_mode):
            info['link_target'] = os.readlink(p)
        if stat.S_ISREG(st.st_mode):
            data = p.read_bytes()
            info['sha256'] = hashlib.sha256(data).hexdigest()
            info['read_size'] = len(data)
    except FileNotFoundError:
        info = {'path': str(p), 'exists_lstat': False}
    except Exception as e:
        info = {'path': str(p), 'inspection_error': f'{type(e).__name__}: {e}'}
    print(json.dumps(info, sort_keys=True))
st = os.stat(root)
print(json.dumps({'path':'/work','mode':oct(stat.S_IMODE(st.st_mode)),'uid':st.st_uid,'gid':st.st_gid}, sort_keys=True))

from pathlib import Path
import os, stat, hashlib, json
out = []
for name in ('AGENTS.md','CLAUDE.md'):
    p = Path('/work') / name
    try:
        st = os.lstat(p)
        item = {
            'path': str(p),
            'present': True,
            'type': 'regular' if stat.S_ISREG(st.st_mode) else 'symlink' if stat.S_ISLNK(st.st_mode) else 'other',
            'mode': oct(stat.S_IMODE(st.st_mode)),
            'uid': st.st_uid,
            'size': st.st_size,
        }
        if stat.S_ISREG(st.st_mode):
            item['sha256'] = hashlib.sha256(p.read_bytes()).hexdigest()
        if stat.S_ISLNK(st.st_mode):
            item['target'] = os.readlink(p)
    except FileNotFoundError:
        item = {'path': str(p), 'present': False}
    out.append(item)
print(json.dumps(out, sort_keys=True))
print(json.dumps({'work_entries': sorted(p.name for p in Path('/work').iterdir())}, sort_keys=True))
